using namespace std;

const int N = 2008;

struct Tour {
    int to;
    int hour;
    int duration;
    bool used;
};

int n, totalUsed;
vector<vector<Tour>> graph(N);
bool vis[N];

bool exploreDepthFirst(int v, int target);
bool checkReachability(int v, Tour &t);
int calculateEndTime(Tour &t, int now);
int depthFirstSearch(int v, int now);
void travelCase(int tci);
int startProgram();

bool exploreDepthFirst(int v, int target) {
    vis[v] = true;
    if (v == target) return true;

    for (Tour &t : graph[v]) {
        if (!vis[t.to] && exploreDepthFirst(t.to, target)) return true;
    }

    return false;
}

bool checkReachability(int v, Tour &t) {
    vis[v] = true;
    if (v == t.to) return true;

    for (Tour &tt : graph[v]) {
        if (!tt.used && !vis[tt.to] && checkReachability(tt.to, t)) return true;
    }

    return false;
}

int calculateEndTime(Tour &t, int now) {
    int end_time = now + t.duration;
    if (end_time < t.hour) return t.hour;
    return end_time;
}

int depthFirstSearch(int v, int now) {
    int res = 0;

    for (Tour &t : graph[v]) {
        if (!t.used) {
            if (!checkReachability(v, t)) {
                t.used = true;
                totalUsed++;
                res = max(res, calculateEndTime(t, now) - t.hour);
                res += depthFirstSearch(t.to, calculateEndTime(t, now));
            }
        }
    }

    return res;
}

void travelCase(int tci) {
    cin >> n;

    // Initialize graph
    for (int i = 0; i < N; i++) {
        graph[i].clear();
        vis[i] = false;
    }

    for (int i = 0; i < n; i++) {
        int a, b, c, d;
        cin >> a >> b >> c >> d;
        graph[i].push_back({ a, b, c, false });
    }

    totalUsed = 0;
    int minTime = depthFirstSearch(0, 0);
    cout << "Case " << tci << ": " << minTime << endl;
}

int startProgram() {
    int T;
    cin >> T;

    for (int tci = 1; tci <= T; tci++) {
        travelCase(tci);
    }

    return 0;
}

