#include <iostream>

using namespace std;

int height, width, min_distance;
int height_profile[12][12];
int wall_accumulation[12][12];

bool is_in_range(int y, int x);
int get_accumulated_wall(int y, int x);
bool is_walled(int y, int x);
void fill_wall_acc();
void erode_walls();
void solve();


bool is_in_range(int y, int x) {
    return y >= 0 && y < height && x >= 0 && x < width;
}

int get_accumulated_wall(int y, int x) {
    if (is_in_range(y, x)) {
        return wall_accumulation[y][x];
    }
    return 0;
}

bool is_walled(int y, int x) {
    return get_accumulated_wall(y, x) >= get_accumulated_wall(y-1, x) && get_accumulated_wall(y, x) >= get_accumulated_wall(y+1, x) && get_accumulated_wall(y, x) >= get_accumulated_wall(y, x-1) && get_accumulated_wall(y, x) >= get_accumulated_wall(y, x+1);
}

void fill_wall_acc() {
    for (int i = 0; i < height; i++) {
        for (int j = 0; j < width; j++) {
            if (is_walled(i, j)) {
                wall_accumulation[i][j]++;
            }
        }
    }
}

void erode_walls() {
    for (int i = 0; i < height; i++) {
        for (int j = 0; j < width; j++) {
            int min_neigh = min({get_accumulated_wall(i-1, j), get_accumulated_wall(i+1, j), get_accumulated_wall(i, j-1), get_accumulated_wall(i, j+1)});
            height_profile[i][j] = max(0, height_profile[i][j] - min_distance - min_neigh);
        }
    }
}

void solve() {
    cin >> height >> width >> min_distance;
    for (int i = 0; i < height; i++) {
        for (int j = 0; j < width; j++) {
            cin >> height_profile[i][j];
        }
    }

    int num_iterations = 0;
    while (true) {
        fill_wall_acc();
        erode_walls();
        if (get_accumulated_wall(0, 0) == 0) {
            break;
        }
        num_iterations++;
    }

    cout << num_iterations << endl;
}

int main() {
    int test_cases;
    cin >> test_cases;

    for (int t = 1; t <= test_cases; t++) {
        cout << "Case " << t << ": ";
        solve();
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <cmath>
#include <queue>

#define EPS 1e-9
#define INF 1e9
#define MAXN 105
#define MAXS 1005

using namespace std;

double square(double x) {
    return x * x;
}

double magnitude(pair<double, double> p) {
    return sqrt(square(p.first) + square(p.second));
}

double absolute(double x) {
    return x < 0 ? -x : x;
}

double cross_product(pair<double, double> a, pair<double, double> b) {
    return a.first * b.second - a.second * b.first;
}

double dot_product(pair<double, double> a, pair<double, double> b) {
    return a.first * b.first + a.second * b.second;
}

void dijkstra(vector<vector<pair<int, double>>>& adj, vector<double>& dist, vector<bool>& vis) {
    priority_queue<pair<double, int>, vector<pair<double, int>>, greater<pair<double, int>>> pq;
    fill(dist.begin(), dist.end(), INF);
    fill(vis.begin(), vis.end(), false);
    dist[0] = 0;
    pq.push({0, 0});
    while (!pq.empty()) {
        int u = pq.top().second;
        pq.pop();
        if (vis[u]) continue;
        vis[u] = true;
        for (auto [v, w] : adj[u]) {
            if (dist[v] > dist[u] + w) {
                dist[v] = dist[u] + w;
                pq.push({dist[v], v});
            }
        }
    }
}

bool validate(double t) {
    vector<vector<pair<int, double>>> adj(N + 2);
    vector<double> dist(N + 2, INF);
    vector<bool> vis(N + 2, false);
    for (int i = 0; i < N; ++i) {
        for (int j = i + 1; j < N; ++j) {
            pair<double, double> dP = {P[j].first - P[i].first, P[j].second - P[i].second};
            pair<double, double> dV = {V[j].first - S * t, V[j].second};
            double d = square(dot_product(dV, dV)) - square(S) * (square(dP) - square(t * S));
            if (d < -EPS) return false;
            if (absolute(d) < EPS) {
                adj[i].push_back({j, magnitude(dP) - t * S});
                adj[j].push_back({i, magnitude(dP) - t * S});
            } else {
                double s = (dot_product(dP, dV) + sqrt(d)) / (square(S));
                if (s > -EPS) {
                    adj[i].push_back({j, s});
                    adj[j].push_back({i, s});
                }
            }
        }
        adj[N].push_back({i, absolute(P[i]) - t * S});
        adj[i].push_back({N, absolute(P[i]) - t * S});
        adj[N + 1].push_back({i, absolute(P[i])});
        adj[i].push_back({N + 1, absolute(P[i])});
    }
    adj[N].push_back({N + 1, 0});
    dijkstra(adj, dist, vis);
    return dist[N + 1] < INF;
}

double binary_search() {
    double lo = 0, hi = INF;
    for (int i = 0; i < 100; ++i) {
        double mid = (lo + hi) / 2;
        if (validate(mid)) {
            hi = mid;
        } else {
            lo = mid;
        }
    }
    return (lo + hi) / 2;
}

int main() {
    int T;
    cin >> T;
    for (int t = 1; t <= T; ++t) {
        cin >> N >> S;
        P.resize(N);
        V.resize(N);
        for (int i = 0; i < N; ++i) {
            cin >> P[i].first >> P[i].second >> V[i].first >> V[i].second;
        }
        double ans = binary_search();
        cout << "Case " << t << ": " << ans << endl;
    }
    return 0;
}

