int dynamic_programming(int index, int f_val) {
    if (index >= size) return 0;
    if (farthest[f_val][index] != -1) return farthest[f_val][index];

    int answer = 0;
    for (int inner_index = index; inner_index < size; inner_index++) {
        if (values[inner_index] == f_val || last_index[f_val][values[inner_index]] >= inner_index) {
            answer = max(answer, dynamic_programming(inner_index+1, values[inner_index]) + 1);
        }
    }
    return farthest[f_val][index] = answer;
}

void find_solution() {
    memset(farthest, -1, sizeof(farthest));
    memset(last_index, -1, sizeof(last_index));

    iterate(i, size) {
        iterate(j, 10) {
            last_index[j][i] = (i > 0 ? last_index[j][i-1] : -1);
        }
        last_index[values[i]][i] = i;
    }

    int answer = 0;
    iterate(i, size) {
        if (values[i] != 0) {
            answer = max(answer, dynamic_programming(i+1, values[i]) + 1);
        }
    }

    cout << answer << endl;
}

