int mapping[26];

void readSampleFile() {
    std::ifstream sampleFile("sample");
    int numOfPairs;
    sampleFile >> numOfPairs;
    std::string one, two;
    for(int i = 0; i < numOfPairs; i++) {
        sampleFile >> one >> two;
        for(int j = 0; j < one.length(); j++) {
            mapping[one[j] - 'a'] = two[j];
        }
    }
    sampleFile.close();
}

void applyMapping(std::string& str) {
    for(int i = 0; i < str.length(); i++) {
        if(isalpha(str[i])) {
            str[i] = mapping[str[i] - 'a'];
        }
    }
}

int main() {
    readSampleFile();

    std::ofstream outFile("out");
    std::ifstream inFile("in");
    int numberOfLines;
    inFile >> numberOfLines;
    inFile.ignore();
    for(int i = 0; i < numberOfLines; i++) {
        std::string inputLine;
        getline(inFile, inputLine);
        applyMapping(inputLine);
        outFile << inputLine << std::endl;
    }
    inFile.close();
    outFile.close();

    return 0;
}

