#include <iostream>
#include <vector>
#include <algorithm>

const int NUMBER = 100;
const int CALENDAR = 365;
const int POSITION = 100;
const int DAYS = 7;
const int CALENDARS = 1461;
const int TIME = 600;

class Natural {
private:
    std::vector<int> digits;

public:
    Natural() {
        digits.push_back(0);
    }

    Natural(int num) {
        while (num > 0) {
            digits.push_back(num % NUMBER);
            num /= NUMBER;
        }
    }

    Natural(std::vector<int> numDigits) : digits(numDigits) {}

    Natural operator+(const Natural& other) const {
        std::vector<int> resultDigits(std::max(digits.size(), other.digits.size()) + 1, 0);
        int carry = 0;
        for (int i = 0; i < resultDigits.size(); i++) {
            int sum = carry + (i < digits.size() ? digits[i] : 0) + (i < other.digits.size() ? other.digits[i] : 0);
            resultDigits[i] = sum % NUMBER;
            carry = sum / NUMBER;
        }
        return Natural(resultDigits);
    }

    Natural operator-(const Natural& other) const {
        std::vector<int> resultDigits(digits.begin(), digits.end());
        int carry = 0;
        for (int i = 0; i < other.digits.size() || carry; i++) {
            resultDigits[i] -= carry + (i < other.digits.size() ? other.digits[i] : 0);
            carry = resultDigits[i] < 0;
            if (carry) resultDigits[i] += NUMBER;
        }
        while (resultDigits.size() > 1 && resultDigits.back() == 0) {
            resultDigits.pop_back();
        }
        return Natural(resultDigits);
    }

    Natural operator*(const Natural& other) const {
        std::vector<int> resultDigits(digits.size() + other.digits.size(), 0);
        for (int i = 0; i < digits.size(); i++) {
            int carry = 0;
            for (int j = 0; j < other.digits.size() || carry; j++) {
                long long mul = resultDigits[i + j] + 1LL * digits[i] * (j < other.digits.size() ? other.digits[j] : 0) + carry;
                resultDigits[i + j] = mul % NUMBER;
                carry = mul / NUMBER;
            }
        }
        while (resultDigits.size() > 1 && resultDigits.back() == 0) {
            resultDigits.pop_back();
        }
        return Natural(resultDigits);
    }

    Natural operator/(const Natural& other) const {
        if (*this < other) return Natural();
        Natural quotient, remainder;
        for (int i = digits.size() - 1; i >= 0; i--) {
            remainder = remainder * NUMBER + digits[i];
            int x = 0, l = 0, r = NUMBER - 1;
            while (l <= r) {
                int m = (l + r) / 2;
                if (other * Natural(m) <= remainder) {
                    x = m;
                    l = m + 1;
                } else {
                    r = m - 1;
                }
            }
            quotient.digits.insert(quotient.digits.begin(), x);
            remainder = remainder - other * Natural(x);
        }
        while (quotient.digits.size() > 1 && quotient.digits.back() == 0) {
            quotient.digits.pop_back();
        }
        return quotient;
    }

    Natural operator%(const Natural& other) const {
        return *this - *this / other * other;
    }

    bool operator<(const Natural& other) const {
        if (digits.size() != other.digits.size()) return digits.size() < other.digits.size();
        for (int i = digits.size() - 1; i >= 0; i--) {
            if (digits[i] != other.digits[i]) return digits[i] < other.digits[i];
        }
        return false;
    }
};

Natural gcd(Natural a, Natural b) {
    while (!(b < Natural())) {
        a = a % b;
        std::swap(a, b);
    }
    return a;
}

Natural calculate(const Natural& x, const Natural& y) {
    return x + y - x * y + gcd(x, y) * (x - y);
}

int main() {
    int x, y;
    std::cin >> x >> y;
    Natural a(x), b(y);
    Natural result = calculate(a, b);
    for (int i = result.digits.size() - 1; i >= 0; i--) {
        std::cout << result.digits[i];
    }
    std::cout << std::endl;
    return 0;
}
