int n, r;
int x[11], y[11];

double distance(int i, int j) {
    return hypot(x[j] - x[i], y[j] - y[i]);
}

int sign(int i, int j, int k) {
    return (x[j] - x[i]) * (y[k] - y[i]) - (y[j] - y[i]) * (x[k] - x[i]);
}

double getAngle(int a1, int a2, int a3) {
    double d1 = distance(a1, a2);
    double d2 = distance(a1, a3);
    double dot = (x[a2] - x[a1]) * (x[a3] - x[a1]) + (y[a2] - y[a1]) * (y[a3] - y[a1]);
    return acos(dot / (d1 * d2));
}

int maximumCoveredPoints(double r, int c, int p) {
    int ans = 1;
    for (int i = 0; i < n; i++) {
        if (i != c && distance(c, i) <= r) {
            int count = 1;
            for (int j = 0; j < n; j++) {
                if (j != c && j != i && sign(c, i, j) == 0 && distance(c, j) <= r) {
                    double angle = getAngle(c, i, j);
                    if (angle <= acos(-1) / 2) {
                        count++;
                    }
                }
            }
            ans = max(ans, count);
        }
    }
    return ans;
}

