    queue<pair<int, int>> q;
    q.push({0, 0});
    visited[{0, 0}] = 0;
    X.pb(0);
    Y.pb(0);
    S.pb(0);
    R.pb(-1);

    while (!q.empty()) {
        int cx = q.front().first, cy = q.front().second;
        q.pop();

        for (int i = 0; i < 4; i++) {
            int nx = cx + dx[i];
            int ny = cy + dy[i];
            if (!visited.count({nx, ny})) {
                q.push({nx, ny});
                visited[{nx, ny}] = sz(X);
                X.pb(nx);
                Y.pb(ny);
                S.pb(visited[{cx, cy}] + 1);
                R.pb(i);
            }
        }
    }
}

