matrix operator*(matrix first, matrix second) {
    matrix result;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            result.arr[i][j] = 0;
            for (int k = 0; k < n; k++) {
                result.arr[i][j] += first.arr[i][k] * second.arr[k][j];
            }
        }
    }
    return result;
