    for (int t = 1; t <= T; t++) {
        cin >> n;
        int result = 0;
        for (int i = 1; i <= n; i++) {
            result += solve(n, i);
            result %= M;
        }
        cout << "Case #" << t << ": " << result << endl;
    }

    return 0;
}

