#define ll long long
#define maxn 25
#define MOD 1000000007

ll n;
int b, an;
int a[maxn];
int C[maxn][maxn], fact[maxn], res[maxn][maxn][maxn], num[maxn][maxn * maxn];

inline void Add(int &a, int b) {
    a += b;
    if (a >= MOD) {
        a -= MOD;
    }
}

inline int Mul(int a, int b) {
    return (1LL * a * b) % MOD;
}

int Pow(int a, int b) {
    int res = 1;
    while (b > 0) {
        if (b & 1) {
            res = Mul(res, a);
        }
        a = Mul(a, a);
        b >>= 1;
    }
    return res;
}

int Div(int a, int b) {
    return Mul(a, Pow(b, MOD - 2));
}

void precompute() {
    C[0][0] = 1;
    for (int i = 1; i < maxn; i++) {
        C[i][0] = 1;
        for (int j = 1; j <= i; j++) {
            C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD;
        }
    }

    fact[0] = 1;
    for (int i = 1; i < maxn; i++) {
        fact[i] = Mul(fact[i - 1], i);
    }
}

int F(int pos, int num[maxn][maxn * maxn], int extra) {
    if (pos == an) {
        return fact[extra];
    }

    if (res[pos][extra][num[pos][extra]] != -1) {
        return res[pos][extra][num[pos][extra]];
    }

    int res = 0;
    for (int i = 0; i < an; i++) {
        if (a[pos] == 0 && i == 0) continue;
        if (num[pos][i] == 0) continue;

        int get = Mul(fact[num[pos][i]], Div(C[extra + num[pos][i] - 1][num[pos][i] - 1], fact[num[pos][i] - 1]));
        Add(res, Mul(get, F(pos + 1, num, extra + num[pos][i])));
    }

    return res[pos][extra][num[pos][extra]] = res;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    precompute();

    int tn;
    cin >> tn;

    for (int t = 1; t <= tn; t++) {
        cin >> n >> b;
        an = 0;
        while (n) {
            a[an++] = n % b;
            n /= b;
        }

        memset(num, 0, sizeof(num));
        for (int i = 0; i < an; i++) {
            for (int j = 0; j <= an; j++) {
                cin >> num[i][j];
            }
        }

        memset(res, -1, sizeof(res));
        cout << "Case #" << t << ": " << F(0, num, 0) << endl;
    }

    return 0;
}

