typedef long long Long;

Long pric;
struct thing {
    Long place, num, t;
};
const Long mod = 1e9 + 7;
const int maxn = 1e5;
map<int, Long> ticket;

bool compare(thing a, thing b) {
    if(a.place == b.place) {
        return a.t < b.t;
    }
    return a.place < b.place;
}

Long calculate(Long l, Long r, Long n) {
    return (l + r) * n / 2;
}

void process(int cas) {
    int n, m;
    cin >> n >> m;

    vector<thing> events;
    for(int i = 0; i < m; i++) {
        Long place, num, t;
        cin >> place >> num >> t;
        events.push_back({place, num, t});
    }

    sort(events.begin(), events.end(), compare);

    Long sum = 0, sold = 0, revenue = 0;
    for(int i = 0; i < m; i++) {
        if(events[i].t == BOARDING) {
            sum += events[i].num;
            revenue += pric * events[i].num;
        } else {
            sum -= events[i].num;
            revenue -= calculate(pric, pric - (pric * sum) / mod, events[i].num);
        }
    }

    cout << "Case #" << cas << ": " << revenue << '\n';
}

