int combinations(int k, int n);
int calculate(int x, int y);

int combinations(int k, int n)
{
    if (k < 0 || k > n)
        return 0;
    return num[n][k];
}

int calculate(int x, int y)
{
    if (x < 0 || y < 0)
        return 0;
    if (x == 0 && y == 0)
        return 1;
    return (long long)combinations(x, x + y) * calculate(x - 1, y) % mod;
}

