int solve(int n) {
    std::vector<ll> nums(n);
    for (int i = 0; i < n; i++) {
        std::cin >> nums[i];
    }

    ll maxVal = *std::max_element(nums.begin(), nums.end());
    ll minVal = *std::min_element(nums.begin(), nums.end());
    nod = gcd(maxVal - minVal, minVal);

    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            nod = gcd(nod, std::abs(nums[i] - nums[j]));
        }
    }

    return nod;
}

