double calculateSquare(double x1, double y1, double x2, double y2, double x3, double y3) {
    return 0.5 * std::abs((x1 - x3) * (y2 - y1) - (x1 - x2) * (y3 - y1));
}

double calculateLength(double x, double y) {
    return std::sqrt(x * x + y * y);
}

void calculateAngle(double x1, double y1, double x2, double y2, double& cos_alpha, double& sin_alpha) {
    double len1 = calculateLength(x1, y1);
    double len2 = calculateLength(x2, y2);
    cos_alpha = (x1 * x2 + y1 * y2) / (len1 * len2);
    sin_alpha = (x1 * y2 - x2 * y1) / (len1 * len2);
}

bool isNull(double x) {
    return std::abs(x) < 1e-9;
}

void solve(std::ifstream& input, std::ofstream& output, int case_num) {
    double x1, y1, x2, y2, x3, y3;
    input >> x1 >> y1 >> x2 >> y2 >> x3 >> y3;

    double xx1 = 0, yy1 = 0, xx2 = calculateLength(x2 - x1, y2 - y1), yy2 = 0;
    double cos_alpha, sin_alpha;
    calculateAngle(x2 - x1, y2 - y1, xx2, yy2, cos_alpha, sin_alpha);

    double det = xx2 * yy1 - xx1 * yy2;
    if (isNull(det))
        output << "not possible\n";
    else {
        double a = (yy1 * y3 + xx1 * x3) / det;
        double b = (-yy2 * y3 + xx2 * x3) / det;
        double c = (-yy1 * y2 + xx1 * x2) / det;
        double d = (yy2 * y1 - xx2 * x1) / det;

        double area = calculateSquare(x1, y1, x2, y2, x3, y3);

        output << std::fixed << std::setprecision(9) << a << " " << b << " " << c << " " << d << " " << area << "\n";
    }
}

