            v.pop_back();
            used[i] = false;
        }
    }
}

vector<VI> getRemainingPossibilities(VI possible, int query) {
    vector<VI> res;
    for (int i = 0; i < possible.size(); i++) {
        if (possible[i] != query) {
            res.push_back(possible);
            res.back()[i] = query;
        }
    }
    return res;
}

int processPossibilities(VI possible) {
    if (possible.empty()) return 0;
    if (dp.count(possible)) return dp[possible];

    int &res = dp[possible];
    res = INT_MAX;

    for (int query : possible) {
        for (const VI &pos : perms) {
            vector<VI> next = getRemainingPossibilities(possible, query);
            int steps = max(abs(query - t[possible.size()]), processPossibilities(next));
            res = min(res, steps);
        }
    }

    return res;
}

void evaluate(int pos, VI possible) {
    if (vis.count({pos, possible})) return;
    vis.insert({pos, possible});
    if (possible.empty()) {
        result = min(result, pos);
        return;
    }

    for (int query : possible) {
        for (int i = 0; i < possible.size(); i++) {
            if (possible[i] == query) {
                evaluate(pos + abs(i - t[possible.size()]), getRemainingPossibilities(possible, query));
            }
        }
    }
}

void solve(int testCase) {
    cin >> n;
    perms.clear();
    VI v;
    generatePermutations(0, v);

    for (int i = 0; i < n; i++) {
        int x;
        cin >> x;
        t[i] = x;
    }

    result = INT_MAX;
    VI init;
    for (int i = 0; i < n; i++) {
        init.push_back(i);
    }

    evaluate(0, init);
    cout << result << endl;
}

