    getJie();

    for (n = 1; n <= 100000; n++) {
        int sum = 0;
        for (int j = 0; j <= n; j++)
            sum = (sum + c(n, j) * sign(j) * powMod(j - m, n) % MOD + MOD) % MOD;
        if (sum < 0) cout << sum << endl;
    }

    return 0;
}

