bool can_achieve(int ratio, int req, int quantity) {
    double min_limit = req * 0.9 * ratio / 100.0;
    double max_limit = req * 1.1 * ratio / 100.0;
    return quantity >= min_limit && quantity <= max_limit;
}

int resolve(std::vector<int>& R, std::vector<std::vector<int>>& Q) {
    int total = 0;
    for (int i = 0; i < Q.size(); i++) {
        std::sort(Q[i].begin(), Q[i].end());
        int min_quant = Q[i][0];

        bool process = true;
        for (int j = 1; j < Q[i].size(); j++) {
            if (!can_achieve(R[i], min_quant, Q[i][j])) {
                process = false;
                break;
            }
        }

        if (process) {
            total++;
        }
    }

    return total;
}

