using namespace std;

struct point {
    int x, y;
};

int x[20], y[20], ans[20];

bool cloWeise(const point &a, const point &b, const point &c) {
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x) < 0;
}

vector<point> convexShape(vector<point> p) {
    int n = p.size();
    if (n <= 3) return p;
    sort(p.begin(), p.end(), [](const point &a, const point &b) {
        return a.x < b.x || (a.x == b.x && a.y < b.y);
    });
    vector<point> upper, lower;
    for (int i = 0; i < n; i++) {
        while (upper.size() >= 2 && !cloWeise(upper[upper.size() - 2], upper[upper.size() - 1], p[i])) upper.pop_back();
        while (lower.size() >= 2 && !cloWeise(lower[lower.size() - 2], lower[lower.size() - 1], p[i])) lower.pop_back();
        upper.push_back(p[i]);
        lower.push_back(p[i]);
    }
    for (int i = lower.size() - 2; i > 0; i--) upper.push_back(lower[i]);
    return upper;
}

bool onLine(point x, point a, point b) {
    return (x.x - a.x) * (b.y - a.y) == (x.y - a.y) * (b.x - a.x);
}

int main() {
    int t;
    cin >> t;
    while (t--) {
        int n;
        cin >> n;
        for (int i = 0; i < n; i++) {
            cin >> x[i] >> y[i];
            ans[i] = n - 1;
        }
        for (int i = 1; i < (1 << n); i++) {
            vector<point> p;
            for (int j = 0; j < n; j++) {
                if ((i & (1 << j)) > 0) {
                    p.push_back({x[j], y[j]});
                }
            }
            vector<point> figure = convexShape(p);
            for (int j = 0; j < n; j++) {
                if ((i & (1 << j)) == 0) continue;
                for (point f : figure) {
                    if (onLine(f, {x[j], y[j]}, {x[(j + 1) % n]})) {
                        ans[j] = min(ans[j], n - int(figure.size()));
                    }
                }
            }
        }
        for (int i = 0; i < n; i++) {
            cout << ans[i] << " ";
        }
        cout << endl;
    }
    return 0;
}

