bool dfs(vector<vector<Pair> > st) {
    if (check(st)) return true;

    if (hs.count(st)) return false;
    hs.insert(st);

    for (int i = 0; i < st.size(); i++) {
        int cur = st[i].size();
        for (int j = 1; j <= c; j++) {
            int nxt = (cur + j - 1) / j;
            for (int k = 0; k < j; k++) {
                vector<vector<Pair> > tmp = st;
                for (int l = 0; l < nxt; l++) {
                    if (l*j+k < cur) {
                        tmp[l].push_back(st[i][l*j+k]);
                    }
                }
                if (dfs(tmp)) return true;
            }
        }
    }
    return false;
}

