const int mod = 1e9 + 7;
const int max_int = 1e9;

int matrix[10][10];
int x, rows, cols, total;

int count_unhappy() {
    int total_unhappy = 0;
    LOOP(i, rows) {
        LOOP(j, cols) {
            if (matrix[i][j] == 1) {
                if (i - 1 >= 0 && matrix[i - 1][j] == 1) {
                    total_unhappy++;
                }
                if (i + 1 < rows && matrix[i + 1][j] == 1) {
                    total_unhappy++;
                }
                if (j - 1 >= 0 && matrix[i][j - 1] == 1) {
                    total_unhappy++;
                }
                if (j + 1 < cols && matrix[i][j + 1] == 1) {
                    total_unhappy++;
                }
            }
        }
    }
    return total_unhappy;
}

int recursion(int row, int col, int sum) {
    if (row == rows) {
        if (sum == total) {
            return count_unhappy();
        }
        return max_int;
    }
    int result = max_int;
    matrix[row][col] = 0;
    if (col == cols - 1) {
        result = min(result, recursion(row + 1, 0, sum));
    } else {
        result = min(result, recursion(row, col + 1, sum));
    }
    matrix[row][col] = 1;
    if (col == cols - 1) {
        result = min(result, recursion(row + 1, 0, sum + 1));
    } else {
        result = min(result, recursion(row, col + 1, sum + 1));
    }
    return result;
}

