using namespace std;

int n, Q;
vector<vector<int>> D, sum;
vector<int> E, S;
vector<vector<bool>> visited;
vector<vector<double>> times;

double result;
int current_time;

int get(int i, int j) {
    return i >= 0 ? sum[j][i] : 0;
}

void explore(int city, int previous) {
    visited[city][previous] = true;
    for (int i = 0; i < n; i++) {
        if (!visited[i][city] && D[city][i] < Q) {
            int new_time = current_time + D[city][i] / S[city];
            if (new_time < times[i][previous]) {
                times[i][previous] = new_time;
                result = min(result, get(previous, i) + E[i] + times[i][previous]);
                explore(i, previous);
            }
        }
    }
}

void handle_case(int testcase) {
    ifstream input("C.in");
    ofstream output("C1.out");

    input >> n >> Q;
    D.resize(n, vector<int>(n));
    sum.resize(n, vector<int>(n, 0));
    E.resize(n);
    S.resize(n);
    visited.resize(n, vector<bool>(n, false));
    times.resize(n, vector<double>(n, 1e18));

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            input >> D[i][j];
            if (j > 0) sum[i][j] = sum[i][j - 1] + D[i][j];
            else sum[i][j] = D[i][j];
        }
    }

    for (int i = 0; i < n; i++) {
        input >> E[i] >> S[i];
    }

    int start, target;
    input >> start >> target;

    result = 1e18;
    current_time = 0;
    explore(start, target);

    output << "Case #" << testcase << ": " << result << endl;

    input.close();
    output.close();
}

int main() {
    ifstream input("C.in");
    int num_tests;
    input >> num_tests;

    for (int testcase = 1; testcase <= num_tests; testcase++) {
        handle_case(testcase);
    }

    input.close();

    return 0;
}

