double profit(ll mn, ll k) {
    return (b - k * mn) * 1.0 / k;
}

bool can(ll mn, ll k) {
    ll cost = k * mn;
    return cost <= b;
}

ll find_mx(int k) {
    ll low = 1, high = 1e9, ans = -1;
    while (low <= high) {
        ll mid = low + (high - low) / 2;
        if (can(mid, k)) {
            ans = mid;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return ans;
}

