int calculate(int cc, vector<yx>& vv) {
    if (vv.size() == 1) return 0;
    if (re[cc][vv.front().a][vv.front().b] != -1) return re[cc][vv.front().a][vv.front().b];
    int i, j, k, l, x, y, z, ret = 0x3f3f3f3f;
    vector<yx> left, right;
    for (i = 1; i < vv.size(); i++) {
