            l += da[vv[i].b].cd[j] == '0';
            r += db[vv[i].b].cd[j] == '0';
        }
        if (cc < n - 1) {
            x = calculate(cc + 1, left);
            if (l <= r) y = calculate(cc + 1, vv);
            else y = 0x3f3f3f3f;
            z = calculate(cc + 1, right);
            if (x + y + z < ret) {
                ret = x + y + z;
                tt.a = x;
                tt.b = y;
                tt.c = left.size();
                tt.d = right.size();
            }
