    while (testC--) {
        in >> R >> C >> M;

        // Reset variables
        usedMines = 0;
        std::priority_queue<point> priority_queue;

        // Set clicked cell coordinates
        in >> clickY >> clickX;

        // Initialize board and visited arrays
        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) {
                board[i][j] = '.';
                visited[i][j] = false;
            }
        }

        // Add clicked cell to priority queue
        priority_queue.push(point(clickX, clickY, 0));

        while (!priority_queue.empty() && usedMines < M) {
            point p = priority_queue.top();
            priority_queue.pop();

            if (visited[p.y][p.x] || board[p.y][p.x] == '*') {
                continue;
            }

            board[p.y][p.x] = '*';
            visited[p.y][p.x] = true;
            usedMines++;

            for (int i = -1; i <= 1; i++) {
                for (int j = -1; j <= 1; j++) {
                    if (goodPos(p.y + i, p.x + j)) {
                        priority_queue.push(point(p.x + j, p.y + i, distance(p.y + i, p.x + j, clickY, clickX)));
                    }
                }
            }
        }

        // Validate board configuration
        bool valid = true;
        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) {
                if (board[i][j] == '.') {
                    valid = false;
                    break;
                }
            }
        }

        // Output result
        out << "Case #" << caseN++ << ":" << std::endl;
        if (valid) {
            for (int i = 0; i < R; i++) {
                for (int j = 0; j < C; j++) {
                    out << board[i][j];
                }
                out << std::endl;
            }
        } else {
            out << "Impossible" << std::endl;
        }
    }

    in.close();
    out.close();

    return 0;
}

