using namespace std;

int n, m;
double prob[10005];
int c[10005];
vector<double> all;
double dp1[1 << 20][2];
double dp2[1 << 20][2];

void read() {
    cin >> n >> m;
    for(int i = 0; i < n; i++) {
        cin >> prob[i];
    }
    for(int i = 0; i < n; i++) {
        cin >> c[i];
    }
}

void solve() {
    sort(prob, prob + n, greater<double>());
    for(int i = 0; i < n; i++) {
        all.push_back(prob[i]);
    }

    dp1[0][0] = dp1[0][1] = 1.0;

    for(int mask = 1; mask < (1 << m); mask++) {
        dp1[mask][0] = dp1[mask][1] = 0.0;
        for(int i = 0; i < m; i++) {
            if(mask & (1 << i)) {
                dp1[mask][0] += dp1[mask ^ (1 << i)][0] * (1.0 - prob[i]);
                dp1[mask][1] += dp1[mask ^ (1 << i)][1] * (1.0 - prob[i]);
            } else {
                dp1[mask][1] += dp1[mask ^ (1 << i)][1] * prob[i];
            }
        }
    }

    dp2[0][0] = dp2[0][1] = 1.0;

    for(int mask = 1; mask < (1 << (n - m)); mask++) {
        dp2[mask][0] = dp2[mask][1] = 0.0;
        for(int i = 0; i < (n - m); i++) {
            if(mask & (1 << i)) {
                dp2[mask][0] += dp2[mask ^ (1 << i)][0] * (1.0 - all[i]);
                dp2[mask][1] += dp2[mask ^ (1 << i)][1] * (1.0 - all[i]);
            } else {
                dp2[mask][1] += dp2[mask ^ (1 << i)][1] * all[i];
            }
        }
    }

    double ans = 0.0;
    for(int mask1 = 0; mask1 < (1 << m); mask1++) {
        for(int mask2 = 0; mask2 < (1 << (n - m)); mask2++) {
            double cur_prob = dp1[mask1][1] * dp2[mask2][1];
            int sum = 0;
            for(int i = 0; i < m; i++) {
                if(mask1 & (1 << i)) {
                    sum += c[i];
                }
            }
            ans += cur_prob * (sum / (sum + 1.0));
        }
    }

    cout << ans << endl;
}

int main() {
    int t;
    cin >> t;
    while(t--) {
        read();
        solve();
    }
    return 0;
}

