    return (a * b) % MOD;
}

int findPower(int base, int exp) {
    int result = 1;
    while (exp > 0) {
        if (exp % 2 == 1) {
            result = (result * base) % MOD;
        }
        base = (base * base) % MOD;
        exp /= 2;
    }
    return result;
}

int reverse(int a) {
    return findPower(a, MOD - 2);
}

int divideValues(int a, int b) {
    return (a * reverse(b)) % MOD;
}

