void play(int column, int player) {
    for(int i = n - 1; i >= 0; i--) {
        if(board[i][column] == 0) {
            board[i][column] = player;
            return;
        }
    }
}

void checkBoard() {
    vector<vector<int>> transposed(n, vector<int>(n));
    vector<vector<int>> diagonal(2 * n - 1, vector<int>(n));

    for(int i = 0; i < n; i++) {
        for(int j = 0; j < n; j++) {
            transposed[j][i] = board[i][j];
            diagonal[i + j][j] = board[i][j];
        }
    }

    board = transposed;

    if(checkForWin() || checkForWin() || checkForWin()) {
        blueWins = true;
    }

    board = diagonal;

    if(checkForWin() || checkForWin() || checkForWin()) {
        redWins = true;
    }
}

bool checkForWin() {
    for(int i = 0; i < n; i++) {
        for(int j = 0; j < n; j++) {
            if(board[i][j] == 0) continue;

            if(j + k <= n) {
                bool win = true;
                for(int l = 1; l < k; l++) {
                    if(board[i][j] != board[i][j + l]) {
                        win = false;
                        break;
                    }
                }

                if(win) return true;
            }

            if(i + k <= n) {
                bool win = true;
                for(int l = 1; l < k; l++) {
                    if(board[i][j] != board[i + l][j]) {
                        win = false;
                        break;
                    }
                }

                if(win) return true;
            }

            if(i + k <= n && j + k <= n) {
                bool win = true;
                for(int l = 1; l < k; l++) {
                    if(board[i][j] != board[i + l][j + l]) {
                        win = false;
                        break;
                    }
                }

                if(win) return true;
            }

            if(i + k <= n && j - k >= -1) {
                bool win = true;
                for(int l = 1; l < k; l++) {
                    if(board[i][j] != board[i + l][j - l]) {
                        win = false;
                        break;
                    }
                }

                if(win) return true;
            }
        }
    }

    return false;
}

