const int IMPNUM = 100000;

int main() {
    int cases;
    cin >> cases;

    for (int t = 0; t < cases; t++) {
        int modules, voltage;
        cin >> modules >> voltage;

        vector<int> gates(modules), nodes(modules), channels(modules);
        for (int i = 0; i < modules; i++) {
            cin >> gates[i] >> nodes[i] >> channels[i];
        }

        vector<vector<int>> dp(modules+1, vector<int>(IMPNUM+1, IMPNUM));
        dp[0][0] = 0;

        for (int i = 1; i <= modules; i++) {
            for (int j = 0; j <= IMPNUM; j++) {
                for (int k = 0; k <= min(j, gates[i-1]); k++) {
                    dp[i][j] = min(dp[i][j], max(dp[i-1][j-k], nodes[i-1] + dp[i-1][j-gates[i-1]-k]) + channels[i-1]);
                }
            }
        }

        int result = dp[modules][voltage];
        if (result == IMPNUM) {
            cout << "IMPOSSIBLE" << endl;
        } else {
            cout << result << endl;
        }
    }

    return 0;
