const ld pi = 3.1415926535897932384626;

struct node {
    ld h, r, csa;
};

bool check(node a, node b) {
    return a.r < b.r;
}

int main() {
    ll t, n, i, j, k, l;
    cin >> t;

    while (t--) {
        cin >> n >> k;
        vector<node> nodes(n);
        for (i = 0; i < n; i++) {
            cin >> nodes[i].r >> nodes[i].h;
            nodes[i].csa = 2 * pi * nodes[i].r * nodes[i].r + 2 * pi * nodes[i].r * nodes[i].h;
        }

        sort(nodes.begin(), nodes.end(), check);

        ld ans2 = 0.0;
        priority_queue<ld> pq;

        for (i = 0; i < k-1; i++) {
            pq.push(nodes[i].csa);
