        }

        ld ans = 0.0;
        for (i = k-1; i < n; i++) {
            pq.push(nodes[i].csa);
            ans2 += nodes[i].csa;
            ans = max(ans, ans2 + pi * nodes[i].r * nodes[i].r);
            ans2 -= pq.top();
            pq.pop();
        }

        cout << fixed << setprecision(10) << ans << endl;
