#include <iostream>
#include <vector>
using namespace std;

enum MOVE {
    RIGHT,
    LEFT,
    DOWN_RIGHT,
    DOWN_LEFT
};

int R, C, F;

int computePath(vector<vector<char>>& maze, int i, int j, int cost) {
    if (i < 0 || i >= R || j < 0 || j >= C || maze[i][j] == '#') {
        return INT_MAX;
    }

    if (i == R - 1 && j == C - 1) {
        return cost;
    }

    int minCost = INT_MAX;

    if (i + 1 < R) {
        int newCost = (maze[i][j] == '.' && maze[i+1][j] == '.') ? F : 1;
        minCost = min(minCost, computePath(maze, i+1, j, cost + newCost));
    }

    minCost = min(minCost, computePath(maze, i, j+1, cost + 1));
    minCost = min(minCost, computePath(maze, i+1, j+1, cost + 1));
    minCost = min(minCost, computePath(maze, i+1, j-1, cost + 1));

    return minCost;
}

int main() {
    int T;
    cin >> T;

    while (T--) {
        cin >> R >> C >> F;

        vector<vector<char>> maze(R, vector<char>(C));
        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) {
                cin >> maze[i][j];
            }
        }

        int result = computePath(maze, 0, 0, 0);
        if (result != INT_MAX) {
            cout << result << endl;
        } else {
            cout << "No solution found" << endl;
        }
    }

    return 0;
}

#include <iostream>
#include <vector>
#include <utility>

typedef long long i64;
typedef std::vector<int> VI;
typedef std::vector<VI> VVI;
typedef std::pair<int, int> PII;
typedef std::vector<PII> VPII;

class DisjointSet {
private:
    VI parent;
    int numSets;
public:
    DisjointSet(int n) {
        parent.resize(n);
        for (int i = 0; i < n; ++i) {
            parent[i] = i;
        }
        numSets = n;
    }

    int findRoot(int x) {
        return (x == parent[x] ? x : parent[x] = findRoot(parent[x]));
    }

    void unite(int x, int y) {
        x = findRoot(x);
        y = findRoot(y);
        if (x != y) {
            parent[y] = x;
            numSets--;
        }
    }

    int getNumSets() {
        return numSets;
    }
};

VI primes;

bool isPrime(int n) {
    if (n < 2) return false;
    for (int i = 2; i * i <= n; ++i) {
        if (n % i == 0) return false;
    }
    return true;
}

int solve(VPII& edges, int n) {
    DisjointSet ds(n);
    for (PII& edge : edges) {
        ds.unite(edge.first, edge.second);
    }
    return ds.getNumSets();
}

int main() {
    int t;
    std::cin >> t;

    while (t--) {
        int n, m;
        std::cin >> n >> m;

        VPII edges;
        for (int i = 0; i < m; ++i) {
            int a, b;
            std::cin >> a >> b;
            edges.push_back({a, b});
        }

        std::cout << solve(edges, n) << std::endl;
    }

    return 0;
}

