const double PI = 3.14159265358979323846;

double x[2], y[2];
int ret[2];

double calculate_distance(double x1, double y1, double x2, double y2);
double get_angle(double angle);
void process(double x1, double y1, double x2, double y2, double x3, double y3, int idx);
void execute();

double calculate_distance(double x1, double y1, double x2, double y2) {
    return sqrt(pow(x2 - x1, 2) + pow(y2 - y1, 2));
}

double get_angle(double angle) {
    if (angle < -1) {
        return -1;
    } else if (angle > 1) {
        return 1;
    } else {
        return angle;
    }
}

void process(double x1, double y1, double x2, double y2, double x3, double y3, int idx) {
    double r1, r2;
    double d1 = calculate_distance(x1, y1, x2, y2);
    double d2 = calculate_distance(x1, y1, x3, y3);

    if (d1 == 0 && d2 == 0) {
        r1 = r2 = 0;
    } else {
        double angle = acos(get_angle(((d1 * d1) + (d2 * d2) - (calculate_distance(x2, y2, x3, y3) * calculate_distance(x2, y2, x3, y3)) / (2 * d1 * d2)));

        r1 = (PI * d1 * d1 * angle) / (2 * PI);
        r2 = (PI * d2 * d2 * angle) / (2 * PI);
    }

    ret[idx] = (int)round(r1 + r2);
}

void execute() {
    std::cin >> x[0] >> y[0] >> x[1] >> y[1];

    process(x[0], y[0], x[1], y[1], 0, 0, 0);
    process(x[0], y[0], x[1], y[1], 0, 0, 1);
}

