bool is_tidy(long long n) {
    long long prev_digit = 10;
    while (n > 0) {
        long long digit = n % 10;
        if (digit > prev_digit) {
            return false;
        }
        prev_digit = digit;
        n /= 10;
    }
    return true;
}

