#include <set>
using namespace std;

#define PII pair<int, int>

string s[57];
int n, m, cnt;
vector<int> A[57][57];
set<PII> S;
bool ok;
int dx[4] = {-1, 0, 1, 0};
int dy[4] = {0, 1, 0, -1};

bool inside(int x, int y) {
    return x >= 0 && x < n && y >= 0 && y < m;
}

void go(int x, int y, int dir) {
    if (!inside(x, y) || s[x][y] == '.') return;
    if (S.count({x, y})) ok = true;
    if (!ok) {
        for (int v : A[x][y]) {
            int nx = x + dx[v], ny = y + dy[v];
            if (v == dir || v == (dir + 2) % 4) {
                go(nx, ny, v);
            }
        }
    }
}

void dfs1(int v) {
    S.erase(S.find({v / m, v % m}));
    for (int u : A[v / m][v % m]) {
        dfs1(v + dx[u] * m + dy[u]);
    }
}

void dfs2(int v, int c) {
    S.erase(S.find({v / m, v % m}));
    for (int u : A[v / m][v % m]) {
        int nx = v + dx[u] * m + dy[u];
        if (S.count({nx / m, nx % m})) {
            dfs2(nx, c);
        }
    }
}

int main() {
    cin >> n >> m;
    for (int i = 0; i < n; i++) {
        cin >> s[i];
    }

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < m; j++) {
            if (s[i][j] == '|' || s[i][j] == '-') {
                S.insert({i, j});
                for (int k = 0; k < 4; k++) {
                    int x = i + dx[k], y = j + dy[k];
                    if (inside(x, y) && (s[x][y] == '|' || s[x][y] == '-')) {
                        A[i][j].push_back(k);
                    }
                }
            }
        }
    }

    ok = false;
    for (auto p : S) {
        go(p.first, p.second, -1);
    }

    if (!ok) {
        cout << "IMPOSSIBLE\n";
    } else {
        cout << "POSSIBLE\n";
        for (auto p : S) {
            dfs1(p.first * m + p.second);
        }
        cnt = 0;
        while (!S.empty()) {
            int x = S.begin()->first, y = S.begin()->second;
            dfs2(x * m + y, cnt++);
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < m; j++) {
                if (s[i][j] == '|' || s[i][j] == '-') {
                    int c = A[i][j].size();
                    cout << (c ? '|' : '-');
                } else {
                    cout << s[i][j];
                }
            }
            cout << "\n";
        }
    }

    return 0;
}

