        std::cin >> p[i];
    }

    while (k > 0) {
        double max_probability = 0.0;
        int max_index = -1;
        for (int i = 0; i < n; i++) {
            if (p[i] < 1.0) {
                double new_probability = (p[i] * u + (1 - p[i])) / n;
