int findMaximumCycleLength(const std::vector<int>& bestFriends, std::vector<bool>& visited, int totalFriends, int current, int start, int previous) {
    if (visited[current]) {
        if (current == start || previous == bestFriends[current]) {
            return 1;
        }
        return 0;
    }

    visited[current] = true;
    return 1 + findMaximumCycleLength(bestFriends, visited, totalFriends, bestFriends[current], start, current);
}

