void add(long long p, long long v) {
    for (; p < n; p |= p + 1) manow[p] = (manow[p] + v) % MOD;
}

long long query(long long p) {
    long long res = 0;
    for (; p >= 0; p = (p & (p + 1)) - 1) res = (res + manow[p]) % MOD;
    return res;
}

