ll isqrt(ll n) {
    ll lo = 0, hi = n;
    while (lo < hi) {
        ll mid = (lo + hi + 1) / 2;
        if (mid * mid > n) {
            hi = mid - 1;
        } else {
            lo = mid;
        }
    }
