using namespace std;

vector<int> loc, speed;

int simulate(int bar, int k, int t) {
    int n = loc.size();
    int swaps = 0;

    for(int i = 0; i < n; i++) {
        int time_to_reach = (bar - loc[i]) / speed[i];
        if(time_to_reach <= t) {
            swaps += max(0, min(t - time_to_reach, k - swaps));
        }
    }

    return (swaps >= k) ? swaps : -1;
}

