bool bfs(vector<set<int>> &graph, int vertex, ostream &stream) {
    vector<bool> visited(graph.size(), false);
    queue<pair<int, int>> q;
    visited[vertex] = true;
    q.push({vertex, -1});

    while (!q.empty()) {
        int u = q.front().first;
        int parent = q.front().second;
        q.pop();

        for (int v : graph[u]) {
            if (!visited[v]) {
                visited[v] = true;
                q.push({v, u});
            } else if (v != parent) {
                return true;
            }
        }
    }

    return false;
}

