#include <algorithm>

#define MAXN 105

int E, R, N;
int v[MAXN];
std::map<std::pair<int, int>, int> cache;

int solve(int currentEnergy, int position) {
    if (position == N) {
        return 0;
    }

    if (cache.find({currentEnergy, position}) != cache.end()) {
        return cache[{currentEnergy, position}];
    }

    int result = 0;
    for (int x = 0; x <= currentEnergy; x++) {
        result = std::max(result, x * v[position] + solve(std::min(E, currentEnergy - x + R), position + 1));
    }

    return cache[{currentEnergy, position}] = result;
}

int main() {
    int testCases;
    std::cin >> testCases;

    for (int testCase = 0; testCase < testCases; testCase++) {
        std::cin >> E >> R >> N;
        for (int i = 0; i < N; i++) {
            std::cin >> v[i];
        }

        cache.clear();
        int answer = solve(E, 0);
        std::cout << "Case " << testCase + 1 << ": " << answer << std::endl;
    }

    return 0;
}

