using namespace std;

long long pow2[42];

long long greatestCommonDivisor(long long num1, long long num2) {
    if (num2 == 0) return num1;
    return greatestCommonDivisor(num2, num1 % num2);
}

int main() {
    int testCases;
    cin >> testCases;

    pow2[0] = 1;
    for (int index = 1; index <= 41; index++) {
        pow2[index] = pow2[index - 1] * 2;
    }

    for (int i = 1; i <= testCases; i++) {
        long long numerator, denominator;
        cin >> numerator >> denominator;

        bool isPossible = false;
        if (denominator == 1) {
            isPossible = true;
        } else {
            for (int j = 0; j <= 41; j++) {
                if (denominator == pow2[j]) {
                    isPossible = true;
                    break;
                }
            }
        }

        if (!isPossible) {
            cout << "Case #" << i << ": impossible" << endl;
        } else {
            long long gcd = greatestCommonDivisor(numerator, denominator);
            numerator /= gcd;
            denominator /= gcd;

            int answer = 0;
            while (numerator < denominator) {
                numerator *= 2;
                answer++;
            }

            cout << "Case #" << i << ": " << answer << endl;
        }
    }

    return 0;
}

