void depth_first_search(int x, int y) {
    cod[x][y] = c;

    for (int k = 0; k < 4; k++) {
        int newx = x + dx[k];
        int newy = y + dy[k];
        if (newx >= 0 && newx < h && newy >= 0 && newy < w && a[newx][newy] < a[x][y] && cod[newx][newy] == '.') {
            depth_first_search(newx, newy);
        }
    }
}

