        std::vector<long double> probabilities(n);
        for (int i = 0; i < n; ++i) {
            std::cin >> probabilities[i];
        }

        long double total_sum = 0.0, total_product = 1.0;
        for (int i = 0; i < n; ++i) {
            total_sum += probabilities[i];
            total_product *= probabilities[i];
        }

        std::sort(probabilities.begin(), probabilities.end(), std::greater<long double>());

        long double best = 0.0;
        for (int i = 0; i <= k; ++i) {
            long double sum = total_sum + u * i;
            long double product = total_product * (1.0 - u) + u * i;

            if (sum < (1.0 + epsilon)) {
                best = std::max(best, product);
            } else {
                best = std::max(best, product * (1.0 - (sum - 1.0)));
            }
        }

        std::cout << "Case #" << test_case << ": ";
        std::cout << std::fixed << std::setprecision(20) << best << std::endl;
    }

    return 0;
}

