int findMinSteps(int start, int end, char key) {
    if (start >= end) return 0;
    if (f[start][end][key-'a'] != -1) return f[start][end][key-'a'];

    int result = INF;
    if (a[start] != key) result = min(result, 1 + findMinSteps(start+1, end, a[start]));
    if (a[end] != key) result = min(result, 1 + findMinSteps(start, end-1, a[end]));
    result = min(result, findMinSteps(start+1, end-1, key) + (a[start] != a[end]));

    return f[start][end][key-'a'] = result;
}

