int rows, cols;
int memo[2][4][4][100000];

bool is_valid_positioning(int r, int c, vector<vector<char>>& grid) {
    return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] != '#';
}

bool process(int r, int c, int happiness, bool alice_turn, vector<vector<char>>& grid) {
    if (grid[r][c] == 'H') happiness = 0;
    if (memo[alice_turn][r][c][happiness] != -1) return memo[alice_turn][r][c][happiness];
    if (happiness == 0) return alice_turn;

    bool win = !is_valid_positioning(r, c, grid);
    for (int dr = -1; dr <= 1; ++dr) {
        for (int dc = -1; dc <= 1; ++dc) {
            if (dr == 0 && dc == 0) continue;
            if ((r + dr + c + dc) % 2 == 0) {
                if (is_valid_positioning(r + dr, c + dc, grid)) {
                    win |= process(r + dr, c + dc, happiness - 1, !alice_turn, grid);
                }
            }
        }
    }

    return memo[alice_turn][r][c][happiness] = win;
}

bool can_win(int kr, int kc, int happiness, bool alice_turn, vector<vector<char>>& grid) {
    memset(memo, -1, sizeof(memo));
    return process(kr, kc, happiness, alice_turn, grid);
}

