                int min_height = a[i][j];
                for (int k = 0; k < 4; ++k) {
                    int x = i + dir[k][0];
                    int y = j + dir[k][1];
                    if (x >= 0 && x < n && y >= 0 && y < m) {
                        min_height = min(min_height, water[x][y]);
                    }
                }
                low[i][j] = min_height;
            }
        }

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                a[i][j] = max(a[i][j] - min(a[i][j] - low[i][j], M), 0);
                push(i, j);
            }
        }
    }

    // Display the result
    cout << "Case #" << steps << ": " << steps << endl;

    return 0;
}

bool check() {
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (a[i][j] != 0) {
                return false;
            }
        }
    }
    return true;
}

void push(int x, int y) {
    vis[x][y] = 1;
    Q[0][0] = x;
    Q[0][1] = y;
    int front = 0, rear = 1;
    while (front < rear) {
        x = Q[front][0];
        y = Q[front][1];
        for (int i = 0; i < 4; ++i) {
            int nx = x + dir[i][0];
            int ny = y + dir[i][1];
            if (nx >= 0 && nx < n && ny >= 0 && ny < m && a[nx][ny] != 0 && !vis[nx][ny]) {
                vis[nx][ny] = 1;
                Q[rear][0] = nx;
                Q[rear][1] = ny;
                ++rear;
            }
        }
        ++front;
    }
}

