int numstr, numserv;
vector<set<string>> have(15);
map<bitset<15>, int> ways;

set<string> createTrie(const string &s) {
    set<string> trie;
    string current = "";
    for(char character : s) {
        current += character;
        trie.insert(current);
    }
    return trie;
}

void explore(int at, bitset<15> &currentSet, int anymask) {
    if(at == numstr) {
        ways[currentSet] = max(ways[currentSet], __builtin_popcount(anymask));
        return;
    }
    explore(at + 1, currentSet, anymask);
    for(string &word : have[at]) {
        bool valid = true;
        for(char character : word) {
            if(!currentSet[character - 'a']) {
                valid = false;
                break;
            }
        }
        if(valid) {
            bitset<15> nextSet = currentSet;
            for(char character : word) {
                nextSet[character - 'a'] = true;
            }
            explore(at + 1, nextSet, anymask | (1 << at));
        }
    }
}

void solveCase(int caseNumber) {
    cin >> numstr >> numserv;
    for(int i = 0; i < numstr; i++) {
        string currentString;
        cin >> currentString;
        have[i] = createTrie(currentString);
    }

    ways.clear();
    bitset<15> currentSet;
    explore(0, currentSet, 0);

    int maxWordCount = 0, solutionCount = 0;
    for(auto it = ways.begin(); it != ways.end(); ++it) {
        if(it->second > maxWordCount) {
            maxWordCount = it->second;
            solutionCount = 1;
        } else if(it->second == maxWordCount) {
            solutionCount++;
        }
    }

    cout << "Case #" << caseNumber << ": " << maxWordCount << " " << solutionCount << endl;
}

