using namespace std;

int n, M, t, A, B, C, D, x0, y0, ans;
vector<pair<int, int>> pnt;

int main() {
    ifstream inputFile("in.txt");
    ofstream outputFile("out.txt");

    inputFile >> t;

    for (int test_case = 1; test_case <= t; test_case++) {
        inputFile >> n >> A >> B >> C >> D >> x0 >> y0 >> M;
        ans = 0;
        pnt.clear();
        pnt.push_back({ x0, y0 });

        for (int i = 1; i < n; i++) {
            int x = (A * pnt[i - 1].first + B) % M;
            int y = (C * pnt[i - 1].second + D) % M;
            pnt.push_back({ x, y });
        }

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                for (int l = j + 1; l < n; l++) {
                    if ((pnt[i].first + pnt[j].first + pnt[l].first) % 3 == 0 &&
                        (pnt[i].second + pnt[j].second + pnt[l].second) % 3 == 0) {
                        ans++;
                    }
                }
            }
        }

        outputFile << "Case #" << test_case << ": " << ans << endl;
    }

    inputFile.close();
    outputFile.close();

    return 0;
}
